        public MemoryStream Generate(Age_Rpt_ConsolidatedGroup criteria, List<ConsolidateReport> data)
        {
            var result = new MemoryStream();
            var sheetName = "";
            if (criteria.ReportType == 1)
            {
                sheetName = ResourceExtension.GetResource(ResourceClass, "usernameconsolidatedreport");
            }
            else if (criteria.ReportType == 2)
            {
                sheetName = ResourceExtension.GetResource(ResourceClass, "dailyconsolidatedreport");
            }
            else if (criteria.ReportType == 3)
            {
                sheetName = ResourceExtension.GetResource(ResourceClass, "sportconsolidatedreport");
            }

            var worksheet = _workbook.CreateSheet(sheetName);
            var titleRow = worksheet.CreateRow(0);
            var titleCell = titleRow.CreateCell(0);
            titleCell.SetCellValue(sheetName + " " + criteria.FromDate.ToString("MM/dd/yyyy") + "-->" + criteria.ToDate.ToString("MM/dd/yyyy") + (criteria.Currency == 0 ? " - " + ResourceExtension.GetResource(ResourceClass, "allcurrencies") : " - " + ResourceExtension.GetResource(ResourceClass, "viewunder") + " " + RemotingRef.RefData.GetExchangeData(criteria.Currency).Currency));

            titleCell.CellStyle = _titleStyle;

            // Header
            var headerRow1 = worksheet.CreateRow(1);
            var headerRow2 = worksheet.CreateRow(2);
            var shiftCol = 1;
            if (criteria.ReportType != 1)
            {
                shiftCol = 0;
                headerRow1.CreateCell(0).SetCellValue(criteria.ReportType == 2 ? ResourceExtension.GetResource(ResourceClass, "daily") : ResourceExtension.GetResource(ResourceClass, "sport"));
                headerRow1.GetCell(0).CellStyle = _headerStyle;

                headerRow2.CreateCell(0);
                headerRow2.GetCell(0).CellStyle = _headerStyle;
            }

            headerRow1.CreateCell(1 - shiftCol).SetCellValue(ResourceExtension.GetResource(ResourceClass, "level"));
            headerRow1.GetCell(1 - shiftCol).CellStyle = _headerStyle;
            headerRow1.CreateCell(2 - shiftCol).SetCellValue(ResourceExtension.GetResource(ResourceClass, "username"));
