            headerRow1.CreateCell(12 - shiftCol).SetCellValue(ResourceExtension.GetResource(ResourceClass, "company"));
            headerRow1.GetCell(12 - shiftCol).CellStyle = _headerStyle;
            headerRow1.CreateCell(13 - shiftCol).SetCellValue(ResourceExtension.GetResource(ResourceClass, "betcount"));
            headerRow1.GetCell(13 - shiftCol).CellStyle = _headerStyle;

            headerRow2.CreateCell(1 - shiftCol);
            headerRow2.GetCell(1 - shiftCol).CellStyle = _headerStyle;
            headerRow2.CreateCell(2 - shiftCol);
            headerRow2.GetCell(2 - shiftCol).CellStyle = _headerStyle;
            headerRow2.CreateCell(3 - shiftCol);
            headerRow2.GetCell(3 - shiftCol).CellStyle = _headerStyle;
            headerRow2.CreateCell(4 - shiftCol);
