                cell.CellStyle = style;

                cell = newRow.CreateCell(4 - shiftCol);
                cell.SetCellValue(data[i].Turnover);
                cell.CellStyle = doubleStyle;

                cell = newRow.CreateCell(5 - shiftCol);
                cell.SetCellValue(data[i].MemberWinloss);
                cell.CellStyle = doubleStyle;

                cell = newRow.CreateCell(6 - shiftCol);
                cell.SetCellValue(data[i].MemberComm);
                cell.CellStyle = doubleStyle;

                cell = newRow.CreateCell(7 - shiftCol);
                cell.SetCellValue(data[i].MemberTotal);
                cell.CellStyle = doubleStyleBold;

                cell = newRow.CreateCell(8 - shiftCol);
                cell.SetCellValue(data[i].OwnerTurnover);
                cell.CellStyle = doubleStyle;

                cell = newRow.CreateCell(9 - shiftCol);
                cell.SetCellValue(data[i].OwnerWinloss);
                cell.CellStyle = doubleStyle;

                cell = newRow.CreateCell(10 - shiftCol);
                cell.SetCellValue(data[i].OwnerComm);
                cell.CellStyle = doubleStyle;

                cell = newRow.CreateCell(11 - shiftCol);
                cell.SetCellValue(data[i].OwnerTotal);
                cell.CellStyle = doubleStyleBold;

                cell = newRow.CreateCell(12 - shiftCol);
                cell.SetCellValue(data[i].Company);
                cell.CellStyle = doubleStyle;

                cell = newRow.CreateCell(13 - shiftCol);
                cell.SetCellValue(data[i].BetCount);
                cell.CellStyle = integerStyle;


                if (criteria.ReportType == 2)
                {
                    var cell0 = worksheet.GetRow(i + _startRowNumber).GetCell(0);
                    var lastRowCell0 = worksheet.GetRow(i + _startRowNumber - 1).GetCell(0);
                    if (cell0.StringCellValue == lastRowCell0.StringCellValue)
                    {
                        mergeRowNumber++;
                    }
                    else
                    {
                        mergedCell = worksheet.GetRow(firstMergeRow + _startRowNumber).GetCell(0);
                        mergedCell.CellStyle = mergedCellStyle;
                        mergedCell.CellStyle.VerticalAlignment = VerticalAlignment.Center;
                        if (criteria.BoldExcel)
                        {
                            mergedCell.CellStyle.SetFont(_myBoldFont);
                        }

                        if (mergeRowNumber > 1)
                        {
                            worksheet.AddMergedRegion(new CellRangeAddress(firstMergeRow + _startRowNumber, firstMergeRow + _startRowNumber + mergeRowNumber - 1, 0, 0));
                        }

                        mergedCellStyle = mergedCellStyle = _oddRowStyle;
                        firstMergeRow = i;
